breaking_changes.Adaptation_method:
// Before (CommonJS)
const replace = require('your-lib');

// After (ESM)
import { replaceInFile, replaceInFileSync } from 'your-lib';

// Before
import replace from 'your-lib';
// or
const replace = require('your-lib');

// After
import { replaceInFile, replaceInFileSync } from 'your-lib';

// Before
replace.sync(options);

// After
import { replaceInFileSync } from 'your-lib';
replaceInFileSync(options);

// Before
replace(options, (error, changes) => {
  // ...
});

// After
replaceInFile(options)
  .then(changes => {
    // ...
  })
  .catch(error => {/* ... */});

// Or with async/await:
try {
  const changes = await replaceInFile(options);
} catch (e) {
  // ...
}

// Before (YAML or JS config files)
my-config.js
my-config.yaml

// After (Only JSON is accepted)
my-config.json

// Async: Provide 'fs' object with readFile & writeFile
replaceInFile({
  ...options,
  fs: myCustomFs // must include readFile & writeFile methods
});

// Sync: Provide 'fsSync' with readFileSync & writeFileSync
replaceInFileSync({
  ...options,
  fsSync: myCustomFsSync // must include readFileSync & writeFileSync
});
